SELECT id, service, log_ts, latency_ms, status_code, context, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id, ARRAY_CONTAINS(MAP_KEYS(context), 'trace') AS has_trace, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier AS tier FROM app_logs WHERE latency_ms <= 808
